tring? // 10th, 12th, Semester 1, AWS, etc.\n  tags               String // JSON string array e.g. [\"#Java\", \"#Placement\"]\n  issuer             String?\n  issueDate          String?\n  expiryDate         String?\n  certNumber         String?\n  isFavorite         Boolean             @default(false)\n  isPinned           Boolean             @default(false)\n  isArchived         Boolean             @default(false)\n  isRecycled         Boolean             @default(false)\n  verificationStatus String              @default(\"PENDING\") // PENDING, VERIFIED, REJECTED\n  rejectionReason    String?\n  verifiedBy         String?\n  verifiedAt         DateTime?\n  currentVersion     Int                 @default(1)\n  privacyLevel       String              @default(\"PRIVATE\") // PRIVATE, COLLEGE_ONLY, RECRUITER_ONLY, PUBLIC_VERIFICATION\n  userId             String\n  user               User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  versions           DocumentVersion[]\n  shares             DocumentShare[]\n  accessLogs         DocumentAccessLog[]\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n}\n\nmodel DocumentVersion {\n  id            String   @id @default(uuid())\n  documentId    String\n  document      Document @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  versionNumber Int\n  fileName      String\n  filePath      String\n  fileSize      Int\n  fileHash      String\n  changeNotes   String?\n  uploadedAt    DateTime @default(now())\n}\n\nmodel DocumentShare {\n  id             String    @id @default(uuid())\n  documentId     String\n  document       Document  @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  shareToken     String    @unique\n  passwordHash   String?\n  expiresAt      DateTime?\n  allowDownload  Boolean   @default(true)\n  isRevoked      Boolean   @default(false)\n  viewsCount     Int       @default(0)\n  downloadsCount Int       @default(0)\n  recipientNote  String?\n  createdAt      DateTime  @default(now())\n}\n\nmodel DocumentAccessLog {\n  id          String   @id @default(uuid())\n  documentId  String\n  document    Document @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  action      String // VIEW, DOWNLOAD, VERIFY, SHARE_CREATED, ACCESS_REVOKED\n  performedBy String\n  ipAddress   String?\n  userAgent   String?\n  timestamp   DateTime @default(now())\n}\n\nmodel PlacementDrive {\n  id               String                 @id @default(uuid())\n  companyName      String\n  companyLogo      String?\n  roleTitle        String\n  packageLpa       Float\n  location         String\n  minCgpa          Float\n  eligibleDepts    String // JSON string array e.g. [\"CSE\", \"IT\", \"ECE\"]\n  requiredDocTypes String // JSON string array e.g. [\"Resume\", \"10th Marksheet\", \"Degree Certificate\"]\n  deadline         DateTime\n  status           String                 @default(\"ACTIVE\") // ACTIVE, CLOSED, UPCOMING\n  description      String\n  applications     PlacementApplication[]\n  createdAt        DateTime               @default(now())\n}\n\nmodel PlacementApplication {\n  id             String         @id @default(uuid())\n  driveId        String\n  drive          PlacementDrive @relation(fields: [driveId], references: [id], onDelete: Cascade)\n  studentId      String\n  studentName    String\n  studentDept    String\n  studentCgpa    Float\n  attachedDocIds String // JSON string array of Document IDs\n  status         String         @default(\"APPLIED\") // APPLIED, SHORTLISTED, VERIFIED, REJECTED, OFFERED\n  appliedAt      DateTime       @default(now())\n}\n\nmodel RecruiterRequest {\n  id                String    @id @default(uuid())\n  recruiterName     String\n  companyName       String\n  studentId         String\n  studentName       String?\n  requestedDocTypes String // JSON string array e.g. [\"Resume\", \"Latest Semester Marksheet\"]\n  deadline          DateTime\n  reason            String\n  status            String    @default(\"PENDING\") // PENDING, SUBMITTED, VERIFIED, REJECTED\n  submittedDocIds   String? // JSON string array\n  createdAt         DateTime  @default(now())\n  submittedAt       DateTime?\n}\n\nmodel AcademicSemester {\n  id             String @id @default(uuid())\n  studentId      String\n  semesterNumber Int\n  sgpa           Float\n  credits        Int\n  subjects       String // JSON string array of { code, name, grade, credits }\n}\n\nmodel UserSession {\n  id         String   @id @default(uuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  device     String\n  browser    String\n  ipAddress  String\n  lastActive DateTime @default(now())\n  isCurrent  Boolean  @default(false)\n}\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  action    String\n  category  String // AUTH, DOCUMENT, VERIFICATION, PLACEMENT, SECURITY, ADMIN\n  details   String\n  userEmail String\n  ipAddress String?\n  timestamp DateTime @default(now())\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  message   String\n  type      String // VERIFICATION, REJECTION, PLACEMENT, SHARE, EXPIRY, SYSTEM\n  isRead    Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n}\n",
